// Reader kernel for fuse_diamond elementwise operation.
// Runtime arguments:
//   arg[0] : uint32_t num_tiles - number of tiles to read
//   arg[1] : uint32_t in0_addr - DRAM address of the first input tensor
// No second input for this kernel.

void kernel_main() {
    // Get runtime arguments
    uint32_t num_tiles = get_arg_val<uint32_t>(0);
    uint32_t in0_addr = get_arg_val<uint32_t>(1);

    // Constants
    constexpr uint32_t cb_id_in0 = 0; // input CB
    constexpr uint32_t tile_size_bytes = 32 * 32 * 4; // float32 tile

    // Reserve space in the destination circular buffer for all tiles
    // We'll push each tile after it is read.
    for (uint32_t i = 0; i < num_tiles; ++i) {
        // Reserve a slot in the CB
        uint32_t l1_write_addr = get_write_ptr(cb_id_in0);
        // Compute source address for this tile
        uint32_t src_addr = in0_addr + i * tile_size_bytes;
        // Async read from DRAM into L1
        noc_async_read(src_addr, l1_write_addr, tile_size_bytes);
        // Ensure the read is complete before we push the tile
        noc_async_read_barrier();
        // Push the tile into CB 0
        cb_push_back(cb_id_in0, tile_size_bytes);
    }
}
"}

