// Compute kernel for fuse_diamond elementwise operation.
// Runtime arguments:
//   arg[0] : uint32_t num_tiles - number of tiles to process

void kernel_main() {
    // Runtime arguments
    uint32_t num_tiles = get_arg_val<uint32_t>(0);

    // CB indices
    constexpr uint32_t cb_id_in0 = 0;   // input
    constexpr uint32_t cb_id_out = 16;  // output

    // Tile dimensions
    constexpr uint32_t tile_w = 32;
    constexpr uint32_t tile_h = 32;
    constexpr uint32_t tile_elements = tile_w * tile_h; // 1024
    constexpr uint32_t tile_size_bytes = tile_elements * 4; // float32

    // Process each tile
    for (uint32_t t = 0; t < num_tiles; ++t) {
        // Wait until input tile is ready in CB 0
        cb_wait_front(cb_id_in0, tile_size_bytes);

        // Pointers to L1 memory for input and output tiles
        uint32_t l1_in_addr = get_read_ptr(cb_id_in0);
        uint32_t l1_out_addr = get_write_ptr(cb_id_out);

        // Compute per‑element
        for (uint32_t i = 0; i < tile_elements; ++i) {
            // Load a
            float a = *((volatile float*)(l1_in_addr + i * 4));
            // t = a * a
            float t_val = a * a;
            // u = t + 1, v = t - 1
            float u = t_val + 1.0f;
            float v = t_val - 1.0f;
            // out = u * v  (equivalent to a^4 - 1)
            float out = u * v;
            // Store result
            *((volatile float*)(l1_out_addr + i * 4)) = out;
        }

        // Mark that we have consumed the input tile and produced an output tile
        cb_pop_front(cb_id_in0, tile_size_bytes);
        cb_push_back(cb_id_out, tile_size_bytes);
    }
}
"}

